<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/src/bootstrap.php';require_admin();require_once dirname(__DIR__,2).'/src/admin_layout.php';
$definitions=[
 'skills'=>['label'=>'Skills','table'=>'skills','fields'=>['name'=>'Skill name','category'=>'Category','proficiency'=>'Proficiency (0–100)','label'=>'Display label','sort_order'=>'Display order','is_published'=>'Published']],
 'projects'=>['label'=>'Projects','table'=>'projects','fields'=>['title'=>'Project title','category'=>'Category tags (space separated)','description'=>'Description','technologies'=>'Technologies (comma separated)','project_url'=>'Project URL (optional)','sort_order'=>'Display order','is_published'=>'Published'],'image'=>'image_path','image_label'=>'Project image'],
 'education'=>['label'=>'Education','table'=>'education','fields'=>['institution'=>'Institution','qualification'=>'Qualification','start_year'=>'Start year','end_year'=>'End year','description'=>'Description','sort_order'=>'Display order','is_published'=>'Published']],
 'experiences'=>['label'=>'Experience','table'=>'experiences','fields'=>['organization'=>'Organization','role'=>'Role','start_date'=>'Start date / year','end_date'=>'End date / year','description'=>'Description','sort_order'=>'Display order','is_published'=>'Published']],
 'achievements'=>['label'=>'Achievements','table'=>'achievements','fields'=>['title'=>'Title','issuer'=>'Issuer','award_date'=>'Date','description'=>'Description','sort_order'=>'Display order','is_published'=>'Published'],'image'=>'image_path','image_label'=>'Certificate or award image'],
];
$type=(string)($_GET['type']??'');if(!isset($definitions[$type])){http_response_code(404);exit('Unknown management section.');}$def=$definitions[$type];$table=$def['table'];$schema=$def['fields'];$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);$editing=null;if($id){$s=db()->prepare("SELECT * FROM `$table` WHERE id=?");$s->execute([$id]);$editing=$s->fetch();if(!$editing){http_response_code(404);exit('Record not found.');}}
function clean_uploaded_path($path){$path=(string)$path;return preg_match('~^uploads/(?:projects|achievements|profile)/[a-f0-9]{40}\.(?:jpg|png|webp)$~',$path)?$path:'';}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'save');$postId=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);
 if($action==='delete'&&$postId){$old=null;if(isset($def['image'])){$s=db()->prepare("SELECT image_path FROM `$table` WHERE id=?");$s->execute([$postId]);$old=$s->fetchColumn();}$del=db()->prepare("DELETE FROM `$table` WHERE id=?");$del->execute([$postId]);if($old&&clean_uploaded_path($old)&&is_file(dirname(__DIR__).'/'.$old))@unlink(dirname(__DIR__).'/'.$old);flash('success',$def['label'].' entry deleted.');redirect('admin/manage.php?type='.$type);}
 $data=[];foreach($schema as $field=>$label){if($field==='is_published')$data[$field]=isset($_POST[$field])?1:0;elseif($field==='proficiency'||$field==='sort_order')$data[$field]=(int)($_POST[$field]??0);else $data[$field]=trim((string)($_POST[$field]??''));}
 $required=array_values(array_filter(array_keys($schema),fn($f)=>!in_array($f,['is_published','sort_order','proficiency','label','category','technologies','project_url','start_year','end_year','start_date','end_date','issuer','award_date'],true)));
 $missing=false;foreach($required as $field)if($data[$field]==='')$missing=true;
 $error=$missing?'Complete all required fields.':'';
 if($type==='skills'&&($data['proficiency']<0||$data['proficiency']>100))$error='Skill proficiency must be between 0 and 100.';
 if(in_array('sort_order',array_keys($data),true)&&($data['sort_order']<0||$data['sort_order']>100000))$error='Display order must be between 0 and 100000.';
 if(isset($data['project_url'])&&$data['project_url']!==''&&(!filter_var($data['project_url'],FILTER_VALIDATE_URL)||!in_array(strtolower((string)parse_url($data['project_url'],PHP_URL_SCHEME)),['http','https'],true)))$error='Project links must use http or https.';
 if(isset($data['description'])&&strlen($data['description'])>10000)$error='Descriptions may contain at most 10,000 characters.';
 try{
  if($error===''){
   $columns=$data;
   if($type==='projects'){$slug=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$data['title']);$slug=strtolower(trim(preg_replace('/[^a-zA-Z0-9]+/','-',(string)$slug),'-'));$columns['slug']=$slug?:'project-'.bin2hex(random_bytes(4));}
   if(isset($def['image'])){$bucket=$type==='projects'?'projects':'achievements';$current=clean_uploaded_path($_POST['current_image']??'');$upload=upload_image($_FILES['image_file']??[],$bucket);$columns['image_path']=$upload?:$current;}
   if($postId){$set=[];foreach(array_keys($columns) as $column)$set[]="`$column`=?";$sql="UPDATE `$table` SET ".implode(',',$set).' WHERE id=?';$values=array_values($columns);$values[]=$postId;db()->prepare($sql)->execute($values);}
   else{$keys=array_keys($columns);$quoted=array_map(fn($key)=>"`$key`",$keys);$marks=array_fill(0,count($keys),'?');$sql="INSERT INTO `$table` (".implode(',',$quoted).') VALUES ('.implode(',',$marks).')';db()->prepare($sql)->execute(array_values($columns));}
   flash('success',$def['label'].' entry saved.');redirect('admin/manage.php?type='.$type);
  }
 }catch(Throwable $ex){error_log('Portfolio CRUD error: '.$ex->getMessage());$error='The record could not be saved. Check required fields and database setup.';}
}
$items=db()->query("SELECT * FROM `$table` ORDER BY sort_order ASC, id DESC")->fetchAll();
admin_header('manage.php?type='.$type,$def['label'].' management');
?><div class="admin-actions" style="margin-bottom:1rem"><a class="btn btn-primary" href="?type=<?= e($type) ?>#entry-form">Add <?= e(rtrim($def['label'],'s')) ?></a></div><section class="admin-card"><h2><?= $editing?'Edit entry':'Add / edit entry' ?></h2><?php if(!empty($error)): ?><p class="admin-error"><?= e($error) ?></p><?php endif; ?><form id="entry-form" method="post" enctype="multipart/form-data" class="admin-form" style="margin-top:1rem"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($editing['id']??$id??0) ?>"><?php foreach($schema as $field=>$label): ?><label for="f_<?= e($field) ?>"><?= e($label) ?></label><?php if($field==='is_published'): ?><span class="checkline"><input id="f_<?= e($field) ?>" type="checkbox" name="is_published" value="1" <?= ($editing['is_published']??1)?'checked':'' ?>><span>Show on public website</span></span><?php elseif(in_array($field,['description'],true)): ?><textarea id="f_<?= e($field) ?>" name="<?= e($field) ?>" required><?= e($editing[$field]??'') ?></textarea><?php else: ?><input id="f_<?= e($field) ?>" name="<?= e($field) ?>" value="<?= e($_POST[$field]??$editing[$field]??'') ?>" <?= in_array($field,['name','title','institution','qualification','organization','role'],true)?'required':'' ?> <?= $field==='proficiency'?'type="number" min="0" max="100"':'' ?> <?= $field==='sort_order'?'type="number" min="0"':'' ?>><?php endif; ?><?php endforeach; ?><?php if(isset($def['image'])): ?><label for="image_file"><?= e($def['image_label']) ?> (JPEG, PNG or WebP; max 5 MB)</label><?php if(!empty($editing['image_path'])):?><img src="../<?= e($editing['image_path']) ?>" alt="Current image" style="max-width:180px;max-height:130px;object-fit:cover"><?php endif; ?><input type="hidden" name="current_image" value="<?= e(clean_uploaded_path($editing['image_path']??'')) ?>"><input id="image_file" name="image_file" type="file" accept="image/jpeg,image/png,image/webp"><?php endif; ?><button class="btn btn-primary" type="submit">Save entry</button><?php if($editing): ?><a class="btn btn-outline" href="?type=<?= e($type) ?>">Cancel</a><?php endif; ?></form></section><section class="admin-card" style="margin-top:1rem"><h2>Current <?= e(strtolower($def['label'])) ?> (<?= count($items) ?>)</h2><?php if(!$items): ?><p class="muted">No entries yet.</p><?php else: ?><table class="admin-table"><thead><tr><th>Entry</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $item): $name=$item['name']??$item['title']??$item['qualification']??$item['role']??'Entry'; ?><tr><td><?= e($name) ?></td><td><?= $item['is_published']?'Public':'Hidden' ?></td><td><?= e($item['updated_at']) ?></td><td><div class="admin-actions"><a class="btn btn-small" href="?type=<?= e($type) ?>&id=<?= (int)$item['id'] ?>#entry-form">Edit</a><form class="inline-form" method="post" onsubmit="return confirm('Delete this entry?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="btn btn-small danger" name="action" value="delete">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section><?php admin_footer(); ?>
